import request from '@/utils/request'
// import QS from 'qs'
export function getRulesInfo() {
  return request({
    url: '/trafficLight/getRulesInfo',
    method: 'get'
  })
}
export function updateRulesInfo(params) {
  return request({
    url: '/trafficLight/updateRulesInfo',
    method: 'post',
    data: params
  })
}